#!/usr/bin/env python3
from pathlib import Path
import json

ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'web/data/v24-expansion.js'

entries=[]

def pair(en,el): return {'en':en,'el':el}

def saint(id,en,el,role_en,role_el,feast_en,feast_el,story_en,story_el,source_url,aliases=None,metadata=None,notes_en='',notes_el=''):
    md=metadata or {}
    e={
      'id':id,'name':pair(en,el),'category':'church-saint','role':pair(role_en,role_el),
      'story':pair(story_en,story_el),'feast':pair(feast_en,feast_el),'scripture':'Church tradition / Lives of the Saints',
      'prayer':pair(f'{en}, pray to God for us, that we may grow in repentance, courage, mercy, humility, and faithfulness.',
                    f'{el}, πρέσβευε στον Θεό για μας, ώστε να αυξανόμαστε σε μετάνοια, θάρρος, έλεος, ταπείνωση και πιστότητα.'),
      'notes':pair(notes_en or 'This profile summarizes the cited Orthodox source and distinguishes hagiographic tradition from strictly datable historical evidence.',
                   notes_el or 'Το προφίλ συνοψίζει την παρατιθέμενη ορθόδοξη πηγή και διακρίνει την αγιολογική παράδοση από τα αυστηρά χρονολογήσιμα ιστορικά δεδομένα.'),
      'aliases':aliases or [],'venerated':True,'image':f'web/images/catalog/{id}.svg','sourceUrl':source_url,
      'metadata':md,
      'search':' '.join([en,el,role_en,role_el,feast_en,feast_el,*[str(x) for x in md.values() if isinstance(x,str)]])
    }
    e['knowledge']={
      'en':{'sections':[
        {'title':'Life and setting','text':story_en},
        {'title':'Why this saint is remembered','text':md.get('significance_en', f'Orthodox memory preserves {en} as a witness to repentance, endurance, prayer, and faithfulness to Christ.')},
        {'title':'Searchable themes and associations','text':'; '.join(md.get('themes_en',[])) or role_en},
        {'title':'Source note','text':'The linked Orthodox Church in America life is the primary web source used for this expansion entry. Hagiographic miracle narratives are preserved as tradition rather than silently converted into modern historical claims.'}
      ],'sources':[{'label':pair('Orthodox Church in America — Life of the Saint','Ορθόδοξη Εκκλησία στην Αμερική — Βίος του Αγίου'),'url':source_url}]},
      'el':{'sections':[
        {'title':'Βίος και πλαίσιο','text':story_el},
        {'title':'Γιατί μνημονεύεται','text':md.get('significance_el', f'Η ορθόδοξη μνήμη διαφυλάσσει τον/την {el} ως μαρτυρία μετανοίας, υπομονής, προσευχής και πιστότητας στον Χριστό.')},
        {'title':'Θέματα και συσχετισμοί αναζήτησης','text':'; '.join(md.get('themes_el',[])) or role_el},
        {'title':'Σημείωση πηγής','text':'Ο συνδεδεμένος Βίος Αγίων της Ορθόδοξης Εκκλησίας στην Αμερική (OCA) είναι η κύρια διαδικτυακή πηγή αυτής της νέας καταχώρισης. Οι θαυματουργικές αγιολογικές διηγήσεις διατηρούνται ως παράδοση και δεν παρουσιάζονται ως σύγχρονη ιστοριογραφική απόδειξη.'}
      ],'sources':[{'label':pair('Orthodox Church in America — Life of the Saint','Ορθόδοξη Εκκλησία στην Αμερική — Βίος του Αγίου'),'url':source_url}]}
    }
    entries.append(e)

